import type { InvitationDataInput } from '../../../lib/validation/invitation.ts'
import type { SectionConfig, SectionDef, SectionType, TemplateConfig } from '../../../lib/validation/template.ts'
import { DEMO_TRACKS, DEMO_VIDEO, demoPhoto, demoUrl } from './demoMedia.ts'

/**
 * The six launch templates. This file is the single source of truth for:
 *  - supabase/seed.sql (generated by `npm run seed:generate`)
 *  - "Start from preset" in the admin console
 * Placeholders usable in any section text: {{bride}} {{groom}} {{date}} {{time}} {{city}} {{venue}}
 */

export interface TemplatePreset {
  slug: string
  name: string
  tagline: string
  description: string
  category: string
  culturalTags: string[]
  languages: string[]
  coverImage: string
  previewImages: string[]
  featured: boolean
  config: TemplateConfig
  sections: SectionDef[]
  sample: InvitationDataInput
}

const s = (key: string, type: SectionType, config: SectionConfig = {}, enabled = true): SectionDef => ({
  key,
  type,
  enabled,
  config,
})

